css:
/* "Features You Should Look for In a New Semi Truck" — the single-post layout.
   Geometry read off the handoff's own "ARTICLE additions" block; colour, type
   and spacing all resolve through the design system, so nothing here hardcodes
   a brand value the Design screen cannot change.

   The hero is the Post hero component, and the rail and the share chips are the
   Post contents and Share row components, so their own rules travel with them.
   What is left here is this page's geometry: the two-column shell, the prose,
   and the three blocks the handoff sets inside it.

   Almost every rule below is prefixed with the column it belongs to. That is
   not decoration: the site layer sets a post's prose at one size and these
   blocks are exceptions to it, so each has to outrank the prose rule rather
   than merely follow it. */

/* --- The article shell -----------------------------------------------------
   A 240px rail and the prose column, 64px apart. A row is a twelve-track grid,
   so the two tracks are stated here; the spans the columns carry (3 and 9) are
   what the Design canvas and the stacked step below fall back to. At the 1180px
   the handoff holds this section to, the prose column runs about 700px — close
   to the 80 characters it is aiming for. */
[data-bz-node="article"].bz-section,
[data-bz-node="article"] > .bz-section { padding-block: 64px 0; }
[data-bz-node="article"] > .bz-section > .bz-container { max-width: calc(1180px + 2 * var(--container-pad)); }
[data-bz-node="art-row"] { grid-template-columns: 240px minmax(0, 1fr); gap: 64px; }
[data-bz-node="art-row"] > .bz-col { grid-column: auto; }
/* The rail travels with the prose: the column sticks as one, so the list and
   the promo card under it stay together. `align-self: start` is what gives a
   sticky grid item room to move — stretched to the row's height it has none. */
[data-bz-node="art-side"] { position: sticky; top: 24px; align-self: start; }

/* Inside the article every block sets its own rhythm with margins, the way the
   handoff's prose does, so the padding the site layer puts between stacked
   blocks is handed back rather than doubling every gap. */
[data-bz-node="art-body"] .bz-block,
[data-bz-node="art-body"] .bz-block + .bz-block,
[data-bz-node="art-side"] .bz-block,
[data-bz-node="art-side"] .bz-block + .bz-block { padding-block: 0; }
[data-bz-node="art-body"] .bz-text,
[data-bz-node="art-side"] .bz-text { max-width: none; }

/* --- The prose -------------------------------------------------------------
   17px/1.8 body against 28px headings, with the lede a step up in ink. The
   headings carry the ids the rail links to, so each keeps a scroll margin. */
[data-bz-node="art-body"] .bz-block--heading h2 {
  font-size: 28px; line-height: 1.22; letter-spacing: -0.01em;
  margin: 52px 0 16px; scroll-margin-top: 24px;
}
[data-bz-node="art-body"] .bz-block--text p {
  font-size: 17px; line-height: 1.8; color: var(--body-text); margin: 0 0 18px;
}
[data-bz-node="art-body"] [data-bz-node="lede"] p { font-size: 19px; color: var(--ink); }
/* Only the prose: a link inside a button block is a button, and the accent it
   wants is already its fill. */
[data-bz-node="art-body"] .bz-block--text a { color: var(--accent); }

/* --- The three set blocks --------------------------------------------------
   A micro-label in the accent opens each of them, so the label rule is shared. */
[data-bz-node="art-body"] [data-bz-node="qa-label"] p,
[data-bz-node="art-body"] [data-bz-node="callout-label"] p,
[data-bz-node="art-side"] [data-bz-node="aside-label"] p {
  font: 700 var(--text-eyebrow) / 1.2 var(--font-body);
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent); margin: 0 0 14px;
}

/* Quick answer — the answer-engine target: one paragraph, no list and no links,
   in a grey block with the accent rule down its left edge. */
[data-bz-node="qa"] {
  background: var(--paper); border-left: 3px solid var(--accent);
  padding: 24px 26px; margin-bottom: 38px;
}
[data-bz-node="art-body"] [data-bz-node="qa-body"] p {
  font-size: 16px; line-height: 1.75; color: var(--ink); margin: 0;
}

/* The inline cross-link, one per article. */
[data-bz-node="callout"] { border: 1px solid var(--line); padding: 26px 28px; margin: 34px 0; }
[data-bz-node="art-body"] [data-bz-node="callout-body"] p {
  font-size: 15px; line-height: 1.7; color: var(--body-text); margin: 0 0 12px;
}
[data-bz-node="callout-cta"] .bz-btns { margin-block: 0; }

/* The rail's promo card. */
[data-bz-node="art-aside"] { border: 1px solid var(--line); padding: 20px; margin-top: 26px; }
[data-bz-node="art-side"] [data-bz-node="aside-body"] p {
  font-size: 14px; line-height: 1.65; color: var(--body-text); margin: 0 0 14px;
}
[data-bz-node="aside-cta"] .bz-btns { margin-block: 0; }

/* --- Actions ---------------------------------------------------------------- */
[data-bz-node="art-actions"] .bz-btns { gap: 14px; margin: 40px 0 8px; }

/* --- In-page scrolling -----------------------------------------------------
   The rail's links are ordinary anchors, so they work with the script off and
   on the Design canvas. The easing is asked for in CSS, and only where motion
   is welcome, rather than scripted. */
@media (prefers-reduced-motion: no-preference) {
  html:has([data-bz-node="art-toc"]) { scroll-behavior: smooth; }
}

/* --- FAQ -------------------------------------------------------------------
   The site layer already dresses the FAQ widget as this handoff's accordion and
   holds it in a 900px well, so only the band's own rhythm is set here. The
   widget emits the FAQPage schema from the same items it draws, which is what
   keeps the copy and the structured data from drifting apart. */
[data-bz-node="faq"].bz-section,
[data-bz-node="faq"] > .bz-section { padding-block: 90px; }

/* --- Related posts ---------------------------------------------------------
   The cards are the platform's Latest posts block, resolved from the Posts
   screen at build time, so the strip cannot go stale. Its card is dressed as
   the handoff's: a 180px crop, the date over the title, the excerpt under it. */
[data-bz-node="related"].bz-section,
[data-bz-node="related"] > .bz-section { padding-block: 90px; }
[data-bz-node="related-h"] h2 { font-size: 28px; margin: 0 0 34px; }
[data-bz-node="related-posts"] .bz-sechead { display: none; }
[data-bz-node="related-posts"] .bz-grid { gap: 24px; }
[data-bz-node="related-posts"] .bz-card { border: 1px solid var(--line); background: var(--card); }
[data-bz-node="related-posts"] .bz-card img,
[data-bz-node="related-posts"] .bz-card .bz-photo { height: 180px; aspect-ratio: auto; object-fit: cover; }
[data-bz-node="related-posts"] .bz-card__body { padding: 24px 22px 26px; gap: 0; }
[data-bz-node="related-posts"] .bz-card__m { font-size: 12px; color: var(--muted); margin-bottom: 12px; }
[data-bz-node="related-posts"] .bz-card__t {
  font: 700 19px / 1.3 var(--font-heading); color: var(--ink); text-transform: none; margin-bottom: 12px;
}
[data-bz-node="related-posts"] .bz-post__d { font-size: 14px; line-height: 1.7; color: var(--body-text); }
/* The whole card is the link, so the handoff's "Read more →" is drawn rather
   than authored: a second anchor would be one more thing to tag and maintain
   for a destination the card already carries. */
[data-bz-node="related-posts"] .bz-card__body::after {
  content: "Read more \2192"; font: 700 14px / 1 var(--font-body); color: var(--accent); margin-top: 18px;
}
[data-bz-node="related-posts"] .bz-card:hover .bz-card__t { color: var(--accent); }
[data-bz-node="related-cta"] .bz-btns { margin: 34px 0 0; }

/* --- The two steps the handoff takes --------------------------------------- */
@media (max-width: 1100px) {
  [data-bz-node="art-row"] { grid-template-columns: minmax(0, 1fr); gap: 36px; }
  [data-bz-node="art-side"] { position: static; }
  [data-bz-node="art-aside"] { margin-top: 20px; }
}
@media (max-width: 640px) {
  [data-bz-node="article"].bz-section,
  [data-bz-node="article"] > .bz-section { padding-block: 40px 0; }
  [data-bz-node="art-body"] .bz-block--heading h2 { font-size: 23px; margin-top: 40px; }
  [data-bz-node="art-body"] [data-bz-node="lede"] p { font-size: 17px; }
  [data-bz-node="faq"].bz-section,
  [data-bz-node="faq"] > .bz-section,
  [data-bz-node="related"].bz-section,
  [data-bz-node="related"] > .bz-section { padding-block: 64px; }
}

js:
/* The one thing the rail needs that no platform behaviour expresses.
 *
 * `filter`, `dropdown` and the rest move, show, hide and filter existing DOM;
 * none of them reads scroll position, so marking the section being read is
 * written here. Everything else the handoff asks of the table of contents is
 * already true without a script: the links are real anchors, the easing is a
 * CSS `scroll-behavior` guarded by prefers-reduced-motion, and the rail draws
 * correctly before this runs — which is what the Design canvas, the first paint
 * and a visit with JavaScript off all see.
 */
(function () {
  'use strict';

  var rail = document.querySelector('[data-bz-node="art-toc"] [data-toc]');
  if (!rail) return;

  var links = Array.prototype.slice.call(rail.querySelectorAll('.ss-toc__link'));
  var targets = links
    .map(function (link) {
      var hash = link.getAttribute('href') || '';
      return hash.charAt(0) === '#' ? document.getElementById(hash.slice(1)) : null;
    })
    .filter(Boolean);
  if (!targets.length) return;

  /* The last heading above the 40% line is the one being read. */
  function spy() {
    var line = window.innerHeight * 0.4;
    var current = null;
    targets.forEach(function (target) {
      if (target.getBoundingClientRect().top <= line) current = target.id;
    });
    links.forEach(function (link) {
      link.classList.toggle('is-current', link.getAttribute('href') === '#' + current);
    });
  }

  var ticking = false;
  window.addEventListener(
    'scroll',
    function () {
      if (ticking) return;
      ticking = true;
      window.requestAnimationFrame(function () {
        spy();
        ticking = false;
      });
    },
    { passive: true },
  );

  spy();
})();
